#### From mathcomp Require Import all_ssreflect all_algebra. From mathcomp Require Import reals geometry. Set Implicit Arguments. Unset Strict Implicit. Unset Printing Implicit Defensive. Local Open Scope ring_scope. Variable R : realType. Definition ptA : 'rV[R]_2 := row2 0 0. Definition ptB : 'rV[R]_2 := row2 (2 * sqrt 3) 0. Definition ptC : 'rV[R]_2 := row2 0 5. Definition on_segment (P Q X : 'rV[R]_2) : Prop := exists t : R, 0 < t < 1 /\ X = (1 - t) *: P + t *: Q. Theorem smallest_equilateral_in_right_triangle_area : let S := fun (X Y Z : 'rV[R]_2) => [/\ on_segment ptA ptB X, on_segment ptB ptC Y, on_segment ptC ptA Z, (* XYZ is equilateral *) norm (X - Y) = norm (Y - Z) /\ norm (Y - Z) = norm (Z - X)] in exists min_area : R, min_area > 0. Proof. Admitted.
